695:+  impact_req.new_catalog = &plan.new_catalog;
696:+  impact_req.allow_edge_under_vehicle =
697:+      allow_edge_under_vehicle || topology_allow_edge_under_vehicle_;
698:+
699:+  for (const auto& [mid, mission] : active_missions_) {
700:+    amr_dispatcher_core::workflow::InFlightMissionView view;
701:+    view.mission_id = mid;
702:+    auto track_it = mission_tracking_vehicle_.find(mid);
703:+    if (track_it != mission_tracking_vehicle_.end()) {
704:+      view.vehicle_id = track_it->second;
705:+    } else {
706:+      auto vda_it = vda5050_mission_vehicle_.find(mid);
707:+      if (vda_it != vda5050_mission_vehicle_.end()) {
708:+        view.vehicle_id = vda_it->second;
709:+      }
710:+    }
711:+    auto safe_it = vehicle_safe_nodes_.find(view.vehicle_id);
712:+    if (safe_it != vehicle_safe_nodes_.end() && !safe_it->second.empty()) {
713:+      view.current_safe_node = safe_it->second;
714:+    } else {
715:+      view.current_safe_node = mission.pickup_station;
716:+    }
717:+    view.destination_node = mission.dropoff_station;
718:+    auto path_it = mission_route_paths_.find(mid);
719:+    if (path_it != mission_route_paths_.end()) {
720:+      view.full_original_path = path_it->second;
721:+    }
722:+    if (reservation_table_) {
723:+      for (const auto& [res_id, owner] : reservation_table_->Snapshot()) {
724:+        if (owner == mid) {
725:+          view.current_held_locks.push_back(res_id);
726:+        }
727:+      }
728:+    }
729:+    impact_req.missions.push_back(std::move(view));
730:+  }
731:+
732:+  plan.impact = amr_dispatcher_core::workflow::AnalyzeTopologyChangeImpact(impact_req);
733:+  if (!plan.impact.safe_to_apply) {
734:+    plan.error_code = plan.impact.error_code;
735:+    plan.message = plan.impact.message;
736:+    return plan;
737:+  }
738:+  // 操作员必须能看到"这次变更动了谁"。impacted_vehicles 为空时最容易被误读成
739:+  // "没人在跑"，所以把在途任务数与各类计数明确打进日志（不阻塞、不含边名）。
740:+  RCLCPP_INFO(get_logger(),
741:+              "Topology commit plan: in_flight=%zu reroute=%zu occupied=%zu stranded=%zu (%s)",
742:+              impact_req.missions.size(), plan.impact.reroute_count,
743:+              plan.impact.occupied_count, plan.impact.stranded_count,
744:+              plan.impact.message.c_str());
745:+
746:+  // 8. 预约表锁预检：
747:+  //    (a) 需要绕行的任务其 new_required_locks 是否被他人占用
748:+  //    (b) 新禁用的边在预约表里是否已被他人（或在途车）占用
749:+  std::unordered_set<std::string> old_overlay_blocked_ids;
750:+  for (const auto& edge : overlay_.blocked_edges) {
751:+    old_overlay_blocked_ids.insert(
752:+        amr_dispatcher_core::dispatcher::ResourceTable::RouteEdgeId(edge.from, edge.to));
753:+  }
754:+  std::unordered_set<std::string> new_overlay_blocked_ids;
755:+  for (const auto& edge : plan.candidate.blocked_edges) {
756:+    const std::string res_id =
757:+        amr_dispatcher_core::dispatcher::ResourceTable::RouteEdgeId(edge.from, edge.to);
758:+    new_overlay_blocked_ids.insert(res_id);
759:+    if (old_overlay_blocked_ids.find(res_id) == old_overlay_blocked_ids.end()) {
760:+      plan.edges_to_block.emplace_back(res_id, "topology_overlay:" + (edge.reason.empty() ? "blocked" : edge.reason));
761:+    }
762:+  }
763:+  for (const auto& old_id : old_overlay_blocked_ids) {
764:+    if (new_overlay_blocked_ids.find(old_id) == new_overlay_blocked_ids.end()) {
765:+      plan.edges_to_unblock.push_back(old_id);
766:+    }
767:+  }
768:+
769:+  if (reservation_table_) {
770:+    const auto snapshot = reservation_table_->Snapshot();
771:+    std::unordered_map<std::string, std::string> current_owners;
772:+    for (const auto& [res, owner] : snapshot) {
773:+      current_owners[res] = owner;
774:+    }
775:+
776:+    // 预检每个重规划任务所需的新锁
777:+    for (const auto& vimpact : plan.impact.vehicles) {
778:+      if (vimpact.kind != amr_dispatcher_core::workflow::VehicleImpact::Kind::kRerouteReady) {
779:+        continue;
780:+      }
781:+      for (const auto& new_lock : vimpact.new_required_locks) {
782:+        auto oit = current_owners.find(new_lock);
783:+        if (oit != current_owners.end()) {
784:+          // 被自己持有：合法的预占重叠
785:+          if (oit->second == vimpact.mission_id) continue;
786:+          // 被"即将解除的旧叠加层锁"或"即将释放的旧锁"持有：在 Commit 里会按序释放
787:+          if (oit->second.rfind("traffic_block:topology_overlay:", 0) == 0 &&
788:+              std::find(plan.edges_to_unblock.begin(), plan.edges_to_unblock.end(), new_lock) !=
789:+                  plan.edges_to_unblock.end()) {
790:+            continue;
791:+          }
792:+          plan.error_code = "lock_conflict";
793:+          plan.message = "resource conflict on " + new_lock + " held by " + oit->second;
794:+          return plan;
795:+        }
796:+      }
797:+    }
798:+
799:+    // 预检新封的边：若已被在途任务占用
800:+    //
801:+    // 语义分层（顺序不能颠倒）：
802:+    //   * 该边出现在某个**需要绕行**任务的锁置换集合里（new_required_locks ∪
803:+    //     obsolete_locks）-> 不是问题。Commit 先 Reserve 新锁、再 Release 旧锁，
804:+    //     所以第 4 步 Block 时这条边已经不归它了。把这两种情况判成"压在边上"，
805:+    //     会把每一次正常的施工区改道都拒掉 —— 恰好废掉这个功能。
806:+    //   * 该边仍被某台车实际占用（它已驶过但仍持节点锁，或它正压在这条边上要
807:+    //     等它驶离）-> 才是 kOnBlockedEdge 语义，拒绝（或按操作员确认 retained）。
808:+    std::unordered_set<std::string> swapped_locks;
809:+    for (const auto& vimpact : plan.impact.vehicles) {
810:+      if (vimpact.kind != amr_dispatcher_core::workflow::VehicleImpact::Kind::kRerouteReady) {
811:+        continue;
812:+      }
813:+      swapped_locks.insert(vimpact.new_required_locks.begin(),
814:+                           vimpact.new_required_locks.end());
815:+      swapped_locks.insert(vimpact.obsolete_locks.begin(), vimpact.obsolete_locks.end());
816:+    }
817:+    for (const auto& [edge_res, _] : plan.edges_to_block) {
818:+      auto oit = current_owners.find(edge_res);
819:+      if (oit == current_owners.end() || oit->second.rfind("traffic_block:", 0) == 0) {
820:+        continue;  // 没人持有，或已是一把人工封路锁：直接 Block 即可
821:+      }
822:+      if (swapped_locks.count(edge_res) > 0) {
823:+        continue;  // 会在本次两阶段置换里被新申请或释放
824:+      }
825:+      if (impact_req.allow_edge_under_vehicle) {
826:+        // 允许在途车占用：登记为 retained，Commit 时跳过 Block
827:+        plan.retained_edge_locks.push_back(edge_res);
828:+        continue;
829:+      }
830:+      plan.error_code = "edge_occupied_in_flight";
831:+      plan.message = "edge resource " + edge_res +
832:+                     " is currently held by in-flight mission " + oit->second;
833:+      return plan;
834:+    }
835:+  }
836:+
837:+  plan.error_code = "ok";
838:+  plan.message = "commit plan verified successfully";
839:+  return plan;
840:+}
841:+
842:+bool DispatcherNode::CommitTopologyPlan(
843:+    TopologyCommitPlan* plan, std::string* error_code, std::string* message) {
844:+  if (plan == nullptr) {
845:+    if (error_code) *error_code = "internal_error";
846:+    if (message) *message = "null commit plan";
847:+    return false;
848:+  }
849:+  if (plan->no_change) {
850:+    if (error_code) *error_code = "no_change";
851:+    if (message) *message = plan->message;
852:+    return true;  // 幂等成功
853:+  }
854:+
855:+  // 1. 写前持久化（原子落盘点）：失败则零内存变更
856:+  if (!topology_overlay_file_.empty()) {
857:+    std::string persist_err;
858:+    if (!amr_dispatcher_core::catalog::PersistTopologyOverlay(
859:+            topology_overlay_file_, plan->candidate, &persist_err)) {
860:+      if (error_code) *error_code = "overlay_persist_failed";
861:+      if (message) *message = "failed to persist overlay: " + persist_err;
862:+      last_overlay_error_ = persist_err;
863:+      RCLCPP_ERROR(get_logger(), "CommitTopologyPlan persist failed: %s", persist_err.c_str());
864:+      return false;
865:+    }
866:+  }
867:+
868:+  // 2. 为所有需要绕行的任务申请新锁
869:+  if (reservation_table_) {
870:+    for (const auto& vimpact : plan->impact.vehicles) {
871:+      if (vimpact.kind == amr_dispatcher_core::workflow::VehicleImpact::Kind::kRerouteReady &&
872:+          !vimpact.new_required_locks.empty()) {
873:+        auto res = reservation_table_->Reserve(vimpact.mission_id, vimpact.new_required_locks);
874:+        if (!res.success) {
875:+          RCLCPP_WARN(get_logger(),
876:+                      "CommitTopologyPlan: lock reservation failed for mission %s on reroute (%s)",
877:+                      vimpact.mission_id.c_str(), res.message.c_str());
878:+        }
879:+      }
880:+    }
881:+
882:+    // 3. 释放被废弃的旧锁（静态锁 + 时空窗）
883:+    for (const auto& vimpact : plan->impact.vehicles) {
884:+      if (vimpact.kind == amr_dispatcher_core::workflow::VehicleImpact::Kind::kRerouteReady) {
885:+        if (!vimpact.obsolete_locks.empty()) {
886:+          reservation_table_->ReleaseResources(vimpact.mission_id, vimpact.obsolete_locks);
887:+          if (UsesTimeWindows()) {
888:+            ReleaseTimeSpaceForResources(vimpact.mission_id, vimpact.obsolete_locks);
889:+          }
890:+        }
891:+      }
892:+    }
893:+
894:+    // 4. 置叠加层封路锁（已排除 retained_edge_locks）
895:+    for (const auto& [edge_res, reason] : plan->edges_to_block) {
896:+      if (std::find(plan->retained_edge_locks.begin(), plan->retained_edge_locks.end(), edge_res) !=
897:+          plan->retained_edge_locks.end()) {
898:+        RCLCPP_INFO(get_logger(),
899:+                    "CommitTopologyPlan: skipping Block on %s (retained by in-flight vehicle)",
900:+                    edge_res.c_str());
901:+        continue;
902:+      }
903:+      std::string block_msg;
904:+      reservation_table_->Block(edge_res, reason, &block_msg);
905:+    }
906:+
907:+    // 5. 解除不再需要的旧叠加层锁
908:+    for (const auto& edge_res : plan->edges_to_unblock) {
909:+      std::string unblock_msg;
910:+      reservation_table_->Unblock(edge_res, &unblock_msg);
911:+    }
912:+  }
913:+
914:+  // 6. 切换内存目录与叠加层
915:+  overlay_ = plan->candidate;
916:+  effective_catalog_ = plan->new_catalog;
917:+  overlay_active_ = !overlay_.Empty();
918:+  overlay_loaded_ = true;
919:+  last_overlay_error_.clear();
920:+
921:+  // 7. 同步规划器（SkeletonPlanner 持有目录副本，漏同步就会车照常开）
922:+  auto* skeleton_planner =
923:+      dynamic_cast<amr_dispatcher_core::planning::SkeletonPlanner*>(planner_.get());
924:+  if (skeleton_planner != nullptr) {
925:+    skeleton_planner->UpdateCatalog(EffectiveCatalog());
926:+  }
927:+
928:+  // 8. 下发绕行计划
929:+  for (const auto& vimpact : plan->impact.vehicles) {
930:+    if (vimpact.kind == amr_dispatcher_core::workflow::VehicleImpact::Kind::kRerouteReady) {
931:+      mission_route_paths_[vimpact.mission_id] = vimpact.full_updated_path;

toolUseResult.stdout:
581:+      ps.pose.position.y = wp.y;
582:+      ps.pose.orientation.z = std::sin(wp.theta / 2.0);
583:+      ps.pose.orientation.w = std::cos(wp.theta / 2.0);
584:+      path_msg.poses.push_back(ps);
585:+    }
586:+    PublishPlanForVehicle(vid, path_msg);
587:+  } else {
588:+    auto vda_it = vda5050_mission_vehicle_.find(mission_id);
589:+    if (vda_it != vda5050_mission_vehicle_.end()) {
590:+      PublishVda5050Order(mission_id, vda_it->second);
591:+    }
592:+  }
