595:+DispatcherNode::TopologyCommitPlan DispatcherNode::BuildTopologyCommitPlan(
596:+    const amr_dispatcher_core::catalog::TopologyOverlay& requested,
597:+    const std::string& expected_map_hash, const std::string& operator_id,
598:+    const std::string& reason, bool allow_edge_under_vehicle) {
599:+  TopologyCommitPlan plan;
600:+
601:+  // 0. 功能开关：topology_overlay_file 为空时整个"目录感知封路"是关闭的。
602:+  //    必须显式拒绝，而不是"内存里生效但重启就没了"——那会让操作员以为
603:+  //    施工区已经提交（控制台显示 revision+1），而冷重启后路又通了。
604:+  //    持久化是这套语义的根基（写前提交点），没有它就没有原子性可言。
605:+  if (topology_overlay_file_.empty()) {
606:+    plan.error_code = "overlay_disabled";
607:+    plan.message =
608:+        "runtime topology overlay is disabled (topology_overlay_file is empty); "
609:+        "set it to an absolute path and restart dispatcher_node";
610:+    return plan;
611:+  }
612:+
613:+  // 1. 基础目录可用性
614:+  if (!CatalogLoaded()) {
615:+    plan.error_code = "catalog_unavailable";
616:+    plan.message = "station catalog not loaded";
617:+    return plan;
618:+  }
619:+  const auto& base = catalog_reloader_->catalog();
620:+
621:+  // 2. map_hash 乐观并发（客户端声明期望基线时校验）
622:+  if (!expected_map_hash.empty() && !base.map_hash.empty() &&
623:+      expected_map_hash != base.map_hash) {
624:+    plan.error_code = "map_hash_mismatch";
625:+    plan.message = "expected map_hash " + expected_map_hash +
626:+                   " does not match current base " + base.map_hash;
627:+    return plan;
628:+  }
629:+  // 2b. 请求体自带的 base_map_hash（例如从 GetTopologyOverlay 回读后原样提交）
630:+  //     同样按乐观并发处理：一份针对旧地图写的施工区绝不能套到新地图上。
631:+  //     （在线编辑时该字段可以为空 —— 那时基线就是服务器当前目录。）
632:+  if (!requested.base_map_hash.empty() && !base.map_hash.empty() &&
633:+      requested.base_map_hash != base.map_hash) {
634:+    plan.error_code = "map_hash_mismatch";
635:+    plan.message = "overlay base_map_hash " + requested.base_map_hash +
636:+                   " does not match current base " + base.map_hash;
637:+    return plan;
638:+  }
639:+
640:+  // 3. 规范化 candidate（盖戳基线哈希、版本号递增、时间戳）
641:+  plan.operator_id = operator_id;
642:+  plan.reason = reason;
643:+  plan.candidate = requested;
644:+  plan.candidate.base_map_hash = base.map_hash;
645:+  plan.candidate.revision = overlay_.revision + 1;
646:+  plan.candidate.updated_at = IsoTimestampNow();
647:+  for (auto& edge : plan.candidate.blocked_edges) {
648:+    if (edge.operator_id.empty()) edge.operator_id = operator_id;
649:+    if (edge.reason.empty()) edge.reason = reason;
650:+    if (edge.created_at.empty()) edge.created_at = plan.candidate.updated_at;
651:+  }
652:+  for (auto& edge : plan.candidate.one_way_edges) {
653:+    if (edge.operator_id.empty()) edge.operator_id = operator_id;
654:+    if (edge.reason.empty()) edge.reason = reason;
655:+    if (edge.created_at.empty()) edge.created_at = plan.candidate.updated_at;
656:+  }
657:+  for (auto& marker : plan.candidate.added_markers) {
658:+    if (marker.operator_id.empty()) marker.operator_id = operator_id;
659:+    if (marker.reason.empty()) marker.reason = reason;
660:+    if (marker.created_at.empty()) marker.created_at = plan.candidate.updated_at;
661:+  }
662:+
663:+  // 4. 幂等判定：若与当前叠加层的语义签名相同 -> no_change（200，零写盘零递增）
664:+  if (amr_dispatcher_core::catalog::TopologyOverlaySignature(plan.candidate) ==
665:+      amr_dispatcher_core::catalog::TopologyOverlaySignature(overlay_)) {
666:+    plan.error_code = "no_change";
667:+    plan.message = "requested topology overlay is identical to the active one";
668:+    plan.no_change = true;
669:+    plan.candidate.revision = overlay_.revision;  // 保持旧 revision
670:+    return plan;
671:+  }
672:+
673:+  // 5. 叠加层自洽性校验
674:+  const auto validation =
675:+      amr_dispatcher_core::catalog::ValidateTopologyOverlay(base, plan.candidate);
676:+  if (!validation.ok) {
677:+    plan.error_code = "overlay_invalid";
678:+    plan.message = validation.message;
679:+    return plan;
680:+  }
681:+
682:+  // 6. 应用并分析全局站点强连通性
683:+  plan.new_catalog =
684:+      amr_dispatcher_core::catalog::ApplyTopologyOverlay(base, plan.candidate);
685:+  plan.connectivity =
686:+      amr_dispatcher_core::catalog::AnalyzeTopologyConnectivity(plan.new_catalog);
687:+  if (!plan.connectivity.all_stations_reachable) {
688:+    plan.error_code = "would_disconnect_topology";
689:+    plan.message = plan.connectivity.message;
690:+    return plan;
691:+  }
692:+
693:+  // 7. 组装在途任务视图并分析对在途车辆的影响
694:+  amr_dispatcher_core::workflow::TopologyChangeImpactRequest impact_req;
695:+  impact_req.new_catalog = &plan.new_catalog;
696:+  impact_req.allow_edge_under_vehicle =
697:+      allow_edge_under_vehicle || topology_allow_edge_under_vehicle_;
698:+
699:+  for (const auto& [mid, mission] : active_missions_) {
700:+    amr_dispatcher_core::workflow::InFlightMissionView view;
701:+    view.mission_id = mid;
702:+    auto track_it = mission_tracking_vehicle_.find(mid);
703:+    if (track_it != mission_tracking_vehicle_.end()) {
704:+      view.vehicle_id = track_it->second;
705:+    } else {
706:+      auto vda_it = vda5050_mission_vehicle_.find(mid);
707:+      if (vda_it != vda5050_mission_vehicle_.end()) {
708:+        view.vehicle_id = vda_it->second;
709:+      }
710:+    }
711:+    auto safe_it = vehicle_safe_nodes_.find(view.vehicle_id);
712:+    if (safe_it != vehicle_safe_nodes_.end() && !safe_it->second.empty()) {
713:+      view.current_safe_node = safe_it->second;
714:+    } else {
715:+      view.current_safe_node = mission.pickup_station;
716:+    }
717:+    view.destination_node = mission.dropoff_station;
718:+    auto path_it = mission_route_paths_.find(mid);
719:+    if (path_it != mission_route_paths_.end()) {
720:+      view.full_original_path = path_it->second;
721:+    }
722:+    if (reservation_table_) {
723:+      for (const auto& [res_id, owner] : reservation_table_->Snapshot()) {
724:+        if (owner == mid) {
725:+          view.current_held_locks.push_back(res_id);
726:+        }
727:+      }
728:+    }
729:+    impact_req.missions.push_back(std::move(view));
730:+  }
731:+
732:+  plan.impact = amr_dispatcher_core::workflow::AnalyzeTopologyChangeImpact(impact_req);
733:+  if (!plan.impact.safe_to_apply) {
734:+    plan.error_code = plan.impact.error_code;
735:+    plan.message = plan.impact.message;
736:+    return plan;
737:+  }
738:+  // 操作员必须能看到"这次变更动了谁"。impacted_vehicles 为空时最容易被误读成
739:+  // "没人在跑"，所以把在途任务数与各类计数明确打进日志（不阻塞、不含边名）。
740:+  RCLCPP_INFO(get_logger(),
741:+              "Topology commit plan: in_flight=%zu reroute=%zu occupied=%zu stranded=%zu (%s)",
742:+              impact_req.missions.size(), plan.impact.reroute_count,
743:+              plan.impact.occupied_count, plan.impact.stranded_count,
744:+              plan.impact.message.c_str());
745:+
746:+  // 8. 预约表锁预检：
747:+  //    (a) 需要绕行的任务其 new_required_locks 是否被他人占用
748:+  //    (b) 新禁用的边在预约表里是否已被他人（或在途车）占用
749:+  std::unordered_set<std::string> old_overlay_blocked_ids;
750:+  for (const auto& edge : overlay_.blocked_edges) {
751:+    old_overlay_blocked_ids.insert(
752:+        amr_dispatcher_core::dispatcher::ResourceTable::RouteEdgeId(edge.from, edge.to));
753:+  }
754:+  std::unordered_set<std::string> new_overlay_blocked_ids;
755:+  for (const auto& edge : plan.candidate.blocked_edges) {
756:+    const std::string res_id =
