                                    const std_msgs::msg::String::SharedPtr msg) {
  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(msg->data);
  if (!report.has_value()) {
    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
